<script lang="ts">
 import {onMount} from 'svelte';
 import {invalidateAll} from '$app/navigation';
 import {useLocale,text} from '$lib/shared/presentation/locale';
 import {failureCode,noticeText} from '$lib/shared/presentation/copy';
 import type {CommunityGateway} from '../application/community';
 let {titleId,titleSlug,score,ratingCount,gateway}:{titleId:string;titleSlug:string;score:number;ratingCount:number;gateway:CommunityGateway}=$props();
 const {locale}=useLocale();
 const colors=['#a52a36','#a1362b','#95401f','#87491b','#77531a','#655b1a','#4e621e','#34672c','#20683c','#176648'];
 let dialog:HTMLDialogElement|undefined;
 let account=$state<string|null>(null),value=$state(0),busy=$state(true),error=$state('');
 let generation=0,alive=false;
 async function load(){const token=++generation;busy=true;error='';try{const actor=await gateway.account();const rating=actor?await gateway.myRating(actor,titleId):0;if(alive&&token===generation){account=actor;value=rating;}}catch(failure){if(alive&&token===generation)error=failureCode(failure);}finally{if(alive&&token===generation)busy=false;}}
 onMount(()=>{alive=true;void load();return()=>{alive=false;generation++;};});
 function open(){dialog?.showModal();if(!busy)void load();}
 async function save(next:number){if(!account||busy)return;busy=true;error='';try{await gateway.rating(account,titleId,next);if(!alive)return;value=next;await invalidateAll();dialog?.close();}catch(failure){if(alive)error=failureCode(failure);}finally{if(alive)busy=false;}}
</script>
<button class="rating-trigger" type="button" onclick={open} aria-label={text($locale,'Тайтлды бағалау','Оценить тайтл')}><strong>{ratingCount>0?score.toFixed(2):'—'}</strong><span>{ratingCount} {text($locale,'баға','оценок')}</span><span class="rate-label">{value>0?text($locale,'Бағаң: ','Ваша: ')+value:text($locale,'Бағалау','Оценить')}</span></button>
<dialog bind:this={dialog} class="rating-dialog" aria-labelledby="rating-title"><div class="dialog-head"><h2 id="rating-title">{text($locale,'Тайтлды бағалау','Оценить тайтл')}</h2><button class="button subtle" type="button" onclick={()=>dialog?.close()} aria-label={text($locale,'Жабу','Закрыть')}>×</button></div>{#if busy}<p role="status">{text($locale,'Жүктелуде…','Загрузка…')}</p>{/if}{#if error}<p class="form-message" role="alert">{noticeText($locale,error)}</p>{/if}{#if account}<div class="rating-choices" role="group" aria-label={text($locale,'Сіздің бағаңыз','Ваша оценка')}>{#each colors as color,index}<button class="rating-choice" type="button" style:background-color={color} aria-label={index+1+' / 10'} aria-pressed={value===index+1} disabled={busy} onclick={()=>save(index+1)}>{index+1}</button>{/each}</div>{#if value>0}<button class="remove-rating" type="button" disabled={busy} onclick={()=>save(0)}>{text($locale,'Бағаны алып тастау','Удалить оценку')}</button>{/if}{:else if !busy&&!error}<p>{text($locale,'Бағалау үшін жүйеге кіріңіз.','Войдите, чтобы оценить тайтл.')}</p><a class="button primary" href={'/login?returnTo='+encodeURIComponent('/titles/'+titleSlug)}>{text($locale,'Кіру','Войти')}</a>{/if}</dialog>
<style>
 .rating-trigger{display:flex;align-items:center;text-decoration:none;flex-direction:column;font-size:12px;color:var(--muted);min-height:44px;flex:none;border:0;background:none;cursor:pointer}.rating-trigger strong{color:var(--accent);font-size:21px;line-height:1.3}.rate-label{margin-top:4px;padding:6px 10px;border-radius:6px;background:var(--panel);color:var(--text)}.rating-dialog{width:min(560px,calc(100vw - 24px));padding:16px;border:1px solid var(--line);border-radius:12px;background:var(--panel);color:var(--text);box-shadow:0 24px 72px #0008}.rating-dialog::backdrop{background:#0009}.dialog-head{display:flex;justify-content:space-between;align-items:center;gap:12px}.dialog-head h2{font-size:19px;margin:0}.dialog-head button{min-width:44px;font-size:23px}.rating-choices{display:flex;gap:6px;overflow-x:auto;scrollbar-width:thin;padding:8px 2px 12px;margin-top:12px}.rating-choice{flex:0 0 44px;width:44px;height:44px;color:#fff;font-weight:700;border:2px solid transparent;border-radius:9px;cursor:pointer;scroll-margin:8px}.rating-choice[aria-pressed='true']{border-color:#fff;box-shadow:0 0 0 2px var(--text)}.rating-choice:focus-visible{outline:2px solid var(--text);outline-offset:2px}.rating-choice:disabled{cursor:wait}.remove-rating{min-height:44px;background:none;border:0;color:var(--muted);text-decoration:underline;cursor:pointer;padding:8px 0;font:inherit;font-size:13px}
</style>
